// ---- NAVIGATION ----
let _currentPage = 'dashboard';

function navigateTo(page) {
  _currentPage = page;

  // Update active nav item
  document.querySelectorAll('.nav-item').forEach(el => el.classList.remove('active'));
  const matchingNav = [...document.querySelectorAll('.nav-item')].find(el => {
    const onclick = el.getAttribute('onclick') || '';
    return onclick.includes(`'${page}'`);
  });
  if (matchingNav) matchingNav.classList.add('active');

  // Update page title & breadcrumb
  const titles = {
    dashboard: 'Dashboard',
    clients: 'Client 360',
    prospects: 'Leads Pipeline',
    policies: 'Policy Management',
    'ai-agents': 'AI Agent Hub',
    campaigns: 'Campaigns',
    upsell: 'Growth Track',
    alerts: 'Policy Alerts',
    'pipeline-view': 'Sales Pipeline',
    sales: 'Applications & Proposals',
    products: 'Product Intelligence Hub',
    reports: 'Reports & Analytics',
    calendar: 'Schedule',
    'ai-insights': 'AI Insights',
    claims: 'Claims Management',
    underwriting: 'Underwriting Pipeline',
    settings: 'Settings',
    help: 'Help & Support',
    fna: 'Needs Analysis',
    delivery: 'Policy Delivery',
    leads: 'Leads — Pre-Qualification',
    'inv-accounts': 'Investment Accounts',
    'ret-accounts': 'Annuity Accounts',
    'adv-wealth': 'Wealth Management',
    'adv-estate': 'Estate Planning',
    'adv-smallbiz': 'Small Business Advisory'
  };

  const breadcrumbs = {
    dashboard: 'Home / Dashboard',
    clients: 'Home / Client 360',
    prospects: 'Home / Marketing / Prospects',
    policies: 'Home / Policies',
    'ai-agents': 'Home / AI Agents',
    campaigns: 'Home / Marketing / Campaigns',
    upsell: 'Home / Sales / Growth Track',
    alerts: 'Home / Service / Policy Alerts',
    'pipeline-view': 'Home / Sales / Sales Pipeline',
    sales: 'Home / Sales',
    products: 'Home / Products',
    reports: 'Home / Reports',
    calendar: 'Home / Schedule',
    'ai-insights': 'Home / Insights / AI Insights',
    claims: 'Home / Claims',
    underwriting: 'Home / Sales / Underwriting',
    settings: 'Home / Settings',
    help: 'Home / Help & Support',
    fna: 'Home / Sales / Needs Analysis',
    delivery: 'Home / Insurance / Policy Delivery',
    leads: 'Home / Marketing / Leads',
    'inv-accounts': 'Home / Investments / Investment Accounts',
    'ret-accounts': 'Home / Retirement / Annuity Accounts',
    'adv-wealth': 'Home / Advisory / Wealth Management',
    'adv-estate': 'Home / Advisory / Estate Planning',
    'adv-smallbiz': 'Home / Advisory / Small Business'
  };

  const titleEl = document.getElementById('page-title');
  const bcEl = document.getElementById('page-breadcrumb');
  if (titleEl) titleEl.textContent = titles[page] || page;
  if (bcEl) bcEl.textContent = breadcrumbs[page] || '';

  const content = document.getElementById('page-content');
  if (!content) return;

  // ── AI Insights: use native JSX template (tpl-ai-insights) ──
  // Fall through to template loading below

  // Load page content from template
  const templateId = `tpl-${page}`;
  const tpl = document.getElementById(templateId);

  if (tpl) {
    // Clone the template node (deep clone preserves structure without live bindings)
    const clone = tpl.cloneNode(true);
    content.innerHTML = clone.innerHTML;

    // Re-initialize charts after DOM settles
    if (page === 'dashboard') {
      requestAnimationFrame(() => {
        setTimeout(() => {
          // Only init charts if My Book tab is currently active
          const _mb = document.getElementById('home-pane-mybook');
          if (_mb && _mb.style.display !== 'none') {
            initDashboardCharts();
          }
          animateKPICards();
        }, 80);
      });
    } else if (page === 'reports') {
      requestAnimationFrame(() => {
        setTimeout(() => initReportCharts(), 80);
      });
    } else if (page === 'upsell') {
      initUpsellPage();
    } else if (page === 'alerts') {
      initAlertsPage();
    } else if (page === 'pipeline-view') {
      initPipelineViewPage();
    } else if (page === 'products') {
      requestAnimationFrame(() => setTimeout(() => initProductsPage(), 80));
    } else if (page === 'fna') {
      requestAnimationFrame(() => setTimeout(() => initFNAPage(), 80));
    } else if (page === 'delivery') {
      requestAnimationFrame(() => setTimeout(() => initDeliveryPage(), 80));
    } else if (page === 'leads') {
      requestAnimationFrame(() => setTimeout(() => initLeadsPage(), 80));
    } else if (page === 'campaigns') {
      requestAnimationFrame(() => setTimeout(() => initCampaignsPage(), 80));
    } else if (page === 'underwriting') {
      requestAnimationFrame(() => setTimeout(() => initUnderwritingPage(), 80));
    }
  }
}

// ---- SIDEBAR TOGGLE ----
function toggleSidebar() {
  const sidebar = document.getElementById('sidebar');
  const main = document.getElementById('main-content');
  if (sidebar.style.width === '72px') {
    sidebar.style.width = '260px';
    main.style.marginLeft = '260px';
    sidebar.classList.remove('collapsed');
  } else {
    sidebar.style.width = '72px';
    main.style.marginLeft = '72px';
    sidebar.classList.add('collapsed');
  }
}

