            '</div>' +
            '<div class="af-checklist">' + _afChecklist(af.fundingChecklist) + '</div>' +
          '</div>' +

        '</div>' +
      '</div>';

    /* ── Section B: IPS ── */
    var allocHtml = _afAllocBars(af.targetAllocation);
    var benchHtml = af.benchmarks.length
